package david.manager;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.zip.*;import javax.xml.parsers.*;import org.w3c.dom.*;import org.xml.sax.InputSource;import org.json.*;import org.jf.smali.*;
public class CoreSmokeTest {
 static int checks=0;static void check(boolean b,String name){if(!b)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static String canonical(String xml)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);Document d=f.newDocumentBuilder().parse(new InputSource(new StringReader(xml)));return node(d.getDocumentElement());}
 static String node(Element e){StringBuilder b=new StringBuilder("<"+e.getTagName());SortedMap<String,String>a=new TreeMap<>();NamedNodeMap at=e.getAttributes();for(int i=0;i<at.getLength();i++)a.put(at.item(i).getNodeName(),at.item(i).getNodeValue());b.append(a).append('>');for(Node c=e.getFirstChild();c!=null;c=c.getNextSibling()){if(c instanceof Element)b.append(node((Element)c));else if(c.getNodeType()==Node.TEXT_NODE&&!c.getNodeValue().trim().isEmpty())b.append(c.getNodeValue().trim());}return b.append("</").append(e.getTagName()).append('>').toString();}
 static byte[] utf(String s){return s.getBytes(StandardCharsets.UTF_8);}
 static File assemble(File root,String name,String type,int value)throws Exception{File s=new File(root,name+".smali"),d=new File(root,name+".dex");String text=".class public Ldemo/"+type+";\n.super Ljava/lang/Object;\n.method public static answer()I\n    .registers 1\n    const/16 v0, 0x"+Integer.toHexString(value)+"\n    return v0\n.end method\n";FileOps.writeAtomic(s,utf(text),false);SmaliOptions opts=new SmaliOptions();opts.apiLevel=28;opts.jobs=1;opts.outputDexFile=d.getPath();if(!Smali.assemble(opts,s.getPath()))throw new IOException("Fixture compilation failed");return d;}
 public static void main(String[]args)throws Exception{
  File root=new File(args[0]);root.mkdirs();File f=new File(root,"text.txt");FileOps.writeAtomic(f,utf("one"),false);FileOps.writeAtomic(f,utf("two"),true);check(new String(FileOps.read(f,100),StandardCharsets.UTF_8).equals("two")&&new File(f+".bak").exists(),"atomic save and backup");
  boolean rejected=false;try{FileOps.child(root,"../escape");}catch(IOException e){rejected=true;}check(rejected,"reject unsafe file names");
  File dir=new File(root,"folder");dir.mkdir();FileOps.writeAtomic(new File(dir,"nested.txt"),utf("payload"),false);File zip=new File(root,"folder.zip");FileOps.zip(dir,zip);File extracted=new File(root,"extracted");FileOps.extract(zip,extracted);check(new File(extracted,"folder/nested.txt").isFile(),"ZIP compression and extraction");
  File evil=new File(root,"evil.zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(evil))){out.putNextEntry(new ZipEntry("../outside.txt"));out.write(utf("bad"));out.closeEntry();}rejected=false;try{FileOps.extract(evil,new File(root,"unsafe"));}catch(IOException e){rejected=true;}check(rejected&&!new File(root,"outside.txt").exists()&&!new File(root,"unsafe").exists(),"ZIP traversal rejected and extraction rolled back");
  File changed=new File(root,"changed.zip");FileOps.rewriteZip(zip,changed,Collections.singletonMap("folder/nested.txt",utf("changed")));check(new String(FileOps.zipEntry(changed,"folder/nested.txt",100),StandardCharsets.UTF_8).equals("changed")&&new String(FileOps.zipEntry(zip,"folder/nested.txt",100),StandardCharsets.UTF_8).equals("payload"),"archive edit preserves source");
  rejected=false;try{FileOps.copyTree(dir,new File(dir,"inside"));}catch(IOException e){rejected=true;}check(rejected,"recursive copy inside source rejected");
  Axml basic=new Axml();String plain="<root name=\"\" value=\"Hello &amp; world\"><child value=\"12\"/></root>";check(canonical(basic.decode(basic.encode(plain))).equals(canonical(plain)),"AXML empty strings and XML escaping round-trip");
  int xmls=0;try(ZipFile z=new ZipFile(args[1])){Enumeration<? extends ZipEntry>en=z.entries();while(en.hasMoreElements()){ZipEntry e=en.nextElement();if(e.getName().endsWith(".xml")){byte[] data=FileOps.bytes(z.getInputStream(e),2*1024*1024);if(!Axml.isBinary(data))continue;Axml a=new Axml();String before=a.decode(data),after=new Axml().decode(a.encode(before));if(!canonical(before).equals(canonical(after)))throw new AssertionError("AXML mismatch "+e.getName());xmls++;}}}check(xmls>=1,"AXML round-trip on "+xmls+" uploaded compiled resources");
  File dex1=assemble(root,"classes","Main",42),dex2=assemble(root,"classes2","Second",7);File apk=new File(root,"fixture.apk");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(apk))){for(File d:Arrays.asList(dex1,dex2)){out.putNextEntry(new ZipEntry(d.getName()));out.write(FileOps.read(d,1000000));out.closeEntry();}}
  DexEngine engine=new DexEngine(new File(root,"sessions"));JSONObject loaded=engine.open(apk,new JSONArray().put("classes.dex").put("classes2.dex"));check(loaded.getInt("count")==2,"MultiDex class loading");check(engine.tree("").length()==1&&engine.tree("demo/").length()==2,"DEX package tree");check(engine.search("answer").length()==2,"DEX method search");check(engine.strings("Main").length()>0,"DEX string search");String java=engine.code("Ldemo/Main;","java","auto").getString("text");check(java.contains("42"),"JADX Java decompilation");
  check(!engine.code("Ldemo/Main;","java","simple").getString("text").isEmpty(),"JADX simple mode");check(!engine.code("Ldemo/Main;","java","fallback").getString("text").isEmpty(),"JADX fallback mode");
  String smali=engine.code("Ldemo/Main;","smali","auto").getString("text");engine.save("Ldemo/Main;",smali.replace("0x2a","0x2b"));check(engine.code("Ldemo/Main;","java","auto").getString("text").contains("43"),"Smali edit → assemble → Java reflects change");
  rejected=false;try{engine.save("Ldemo/Main;","invalid smali");}catch(IOException e){rejected=true;}check(rejected&&engine.code("Ldemo/Main;","java","auto").getString("text").contains("43"),"invalid Smali rejected without corrupting DEX");
  File exported=new File(engine.export(root).getString("path"));DexEngine again=new DexEngine(new File(root,"reopened"));again.open(exported,new JSONArray().put("classes.dex").put("classes2.dex"));check(again.code("Ldemo/Main;","java","auto").getString("text").contains("43"),"edited APK export and reopen");engine.close();again.close();
  System.out.println("ALL "+checks+" CORE CHECKS PASSED");
 }
}
